/-- Given [the specified input d](hyp:d), [the specified input w](hyp:w), [observed](goal) is the corresponding construction. -/
def observed {d : ℕ} (w : FullRecord d) : Cov d × Bool × Bool :=
  (w.1, w.2.1, if w.2.1 then w.2.2.2 else w.2.2.1) -- @realizes Y(consistency selection)

f599b4336c231ee3.statement:
/-- [The overlap condition at level eps](goal): [the overlap level eps](hyp:eps) is positive and, on the design cube, [the law P](hyp:P) has a propensity between eps and 1 − eps. -/
def Overlap (eps : ℝ) (P : PrimitiveLaw d) : Prop :=
  0 < eps ∧ ∀ x ∈ cube d, eps ≤ P.e x ∧ P.e x ≤ 1 - eps -- @realizes e(overlap band)

6a05cc281e8d84c1.statement:
/-- Witness-level effect smoothness. After `W` is selected, `rawContrast W` agrees
with the canonical `tau` on the cube.  Given [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the specified input W](hyp:W), [effect holder](goal) is the corresponding construction. -/
def EffectHolder (gamma L : ℝ) (W : PrimitiveLaw d) : Prop := holderNorm (rawContrast W) gamma ≤ ENNReal.ofReal L -- @realizes tau(effect smoothness)

497b82e1488a85d1.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the overlap level eps](hyp:eps), [the specified input n](hyp:n), [the specified input m](hyp:m), [minimax risk](goal) is the corresponding construction. -/
def minimaxRisk (d : ℕ) (alpha beta gamma L eps : ℝ) (n m : ℕ) : ℝ≥0∞ :=
  Causalean.Stat.minimaxValueENNReal (classRisk d alpha beta gamma L eps n m) -- @realizes R(minimax value)

a4764e11ef42b7f9.statement:
/-- Given [the specified input h](hyp:h), [the specified input x](hyp:x), [coarse basis](goal) is the corresponding construction. -/
def coarseBasis (h : ℝ) (x : Cov d) (κ : PolyIdx d) : ℝ :=
  ∏ i, legendre (κ.1 i) ((x i-1/2)/h) -- @realizes r(scaled Legendre vector)

9d760862264b36d2.statement:
/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [the specified input J](hyp:J), [the specified input f](hyp:f), [the specified input x](hyp:x), [proj op](goal) is the corresponding construction. -/
def projOp (d : ℕ) (h : ℝ) (J : ℕ) (f : Cov d → ℝ) (x : Cov d) : ℝ :=
  ∫ xp, fineKernel d h J x xp * f xp ∂locLaw d h -- @realizes Proj(kernel integral)

