/-- Given [the specified input D](hyp:D), [the specified input h](hyp:h), [the specified input J](hyp:J), [rect moments](goal) is the corresponding construction. -/
def rectMoments (D : Dataset d n m) (h : ℝ) (J : ℕ) :
    (PolyIdx d → ℝ) × Matrix (PolyIdx d) (PolyIdx d) ℝ := (rHat D h J, qHat D h J)

aafabbf143a6dcd6.statement:
/-- Given [the overlap level eps](hyp:eps), [the specified input h](hyp:h), [the specified input J](hyp:J), [the specified input D](hyp:D), [t hat](goal) is the corresponding construction: the clipped local-polynomial estimate when the smallest Rayleigh quotient of the empirical Gram matrix is at least the Gram guard level of eps, and zero otherwise. -/
def tHat (eps h : ℝ) (J : ℕ) (D : Dataset d n m) : ℝ :=
  if gramGuard eps ≤ lambdaMin (qHat D h J) then
    clip (∑ u, r0 d h u * ((qHat D h J)⁻¹.mulVec (rHat D h J)) u)
  else 0 -- @realizes That(clipped eigenvalue-guarded decision)

132fe0193ee58858.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input D](hyp:D), [the overlap level eps](hyp:eps), [t up](goal) is the corresponding construction. -/
def tUp (d : ℕ) (alpha beta gamma eps : ℝ) (n m : ℕ) (D : Dataset d n m) : ℝ :=
  tHat eps (hStar d alpha beta gamma n m) (jStar d alpha beta gamma n m) D -- @realizes Tup(tuned upper decision)

7b70fb6a9799df8a.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input w](hyp:w), [the overlap level eps](hyp:eps), [sharp decision](goal) is the corresponding construction. -/
def sharpDecision (d : ℕ) (alpha beta gamma eps : ℝ) (n m : ℕ) (w : Sample d n m) : ℝ :=
  tUp d alpha beta gamma eps n m w.1 -- @realizes Tstar(total data-only decision)

53b0cd4425fb32da.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [upper rate](goal) is the corresponding construction. -/
def upperRate (d : ℕ) (alpha beta gamma : ℝ) (n m : ℕ) : ℝ :=
  max (oracleRate d gamma n) (((n:ℝ)*((n:ℝ)+m))^(-(gamma/bigDelta d alpha beta gamma))) -- @realizes rup(upper rate)

78b8c512157df376.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the overlap level eps](hyp:eps), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input T](hyp:T), [the specified input P](hyp:P), [class risk](goal) is the corresponding construction. -/
def classRisk (d : ℕ) (alpha beta gamma L eps : ℝ) (n m : ℕ) (T : Decision d n m)
    (P : {P : PrimitiveLaw d // PrimitiveClass alpha beta gamma L eps P}) : ℝ≥0∞ := risk T P.1 P.2

c4abeab9df5a7b5b.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input zeta](hyp:zeta), [annotation region](goal) is the corresponding construction. -/
def annotationRegion (d : ℕ) (alpha beta gamma zeta : ℝ) : Set (ℕ × ℕ) :=
  {p | 2 ≤ p.1 ∧ sharpRate d alpha beta gamma p.1 p.2 ≤ zeta * oracleRate d gamma p.1} -- @realizes Bstar(oracle-attainment region) @realizes zeta(tolerance input)

0227f76d0613b97e.statement:
/-- Given [the specified input h](hyp:h), [the specified input delta](hyp:delta), [the specified input a](hyp:a), [the specified input b](hyp:b), [the specified input theta](hyp:theta), [the specified input arm](hyp:arm), [the specified input sigma](hyp:sigma), [the specified input x](hyp:x), [marked mean](goal) is the corresponding construction. -/
def markedMean (h delta a b : ℝ) (theta arm : Bool) (sigma : SignArray d h delta) (x : Cov d) : ℝ :=
  1/2 + b*signField h delta sigma true x + thetaSign arm * markedContrast h a b theta x / 2 -- @realizes b(control amplitude)

c3e9bab13c0592e1.statement:
/-- Given [the specified input H](hyp:H), [the specified input theta](hyp:theta), [sign prior](goal) is the corresponding construction. -/
def signPrior (H : MarkedPriors d) (theta : Bool) : Measure (PriorSign H) :=
  ∑ sigma, ENNReal.ofReal (H.weight theta sigma) • Measure.dirac sigma

080b89f419a24eee.statement:
/-- Given [the specified input H](hyp:H), [the specified input theta](hyp:theta), [the specified input x](hyp:x), [singleton mixture](goal) is the corresponding construction. -/
def singletonMixture (H : MarkedPriors d) (theta : Bool) (x : Cov d) : Measure (Bool × Bool) :=
  ∑ sigma, ENNReal.ofReal (H.weight theta sigma) • conditionalObserved (H.law theta sigma) x

694bea2522de8576.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [the overlap level eps](hyp:eps), [frontier handle](goal) is the corresponding construction. -/
def frontierHandle (d : ℕ) (alpha beta gamma eps : ℝ) (n m : ℕ) : ℝ × (Sample d n m → ℝ) :=
  (sharpRate d alpha beta gamma n m, sharpDecision d alpha beta gamma eps n m) -- @realizes frontierHandle(rate-decision program)
